        a = row['option_a_ratings']
        b = row['option_b_ratings']
        resp = row['response']

        ttb_winner = None
        for i in range(len(a)):
            if a[i] > b[i]:
                ttb_winner = 0
                break
            elif b[i] > a[i]:
                ttb_winner = 1
                break

        if ttb_winner is not None:
            if resp == ttb_winner:
                ttb_matches += 1
            total += 1

    return float(ttb_matches / total) if total > 0 else 0.5

